DROP TABLE IF EXISTS magicprefix;
CREATE TABLE magicprefix (
    "name" TEXT,
    "version" TEXT,
    "spawnable" TEXT,
    "rare" TEXT,
    "level" TEXT,
    "maxlevel" TEXT,
    "levelreq" TEXT,
    "classspecific" TEXT,
    "class" TEXT,
    "classlevelreq" TEXT,
    "frequency" TEXT,
    "group" TEXT,
    "mod1code" TEXT,
    "mod1param" TEXT,
    "mod1min" TEXT,
    "mod1max" TEXT,
    "mod2code" TEXT,
    "mod2param" TEXT,
    "mod2min" TEXT,
    "mod2max" TEXT,
    "mod3code" TEXT,
    "mod3param" TEXT,
    "mod3min" TEXT,
    "mod3max" TEXT,
    "transformcolor" TEXT,
    "itype1" TEXT,
    "itype2" TEXT,
    "itype3" TEXT,
    "itype4" TEXT,
    "itype5" TEXT,
    "itype6" TEXT,
    "itype7" TEXT,
    "etype1" TEXT,
    "etype2" TEXT,
    "etype3" TEXT,
    "etype4" TEXT,
    "etype5" TEXT,
    "multiply" TEXT,
    "add" TEXT
);

BEGIN;
COMMIT;
